"proposal": {
    "capability": "deployment.set-resources",
    "target": {
        "group": "apps",
        "kind": "Deployment",
        "namespace": "shop",
        "name": "reports",
        "uid": "uid-deployment-reports"
    },
    "params": {
        "containers": {
            "renderer": {
                "limits": {
                    "cpu": "1500m"
                }
            }
        }
    },
    "expected_effect": "Raise renderer's CPU limit to 1.5 cores to clear throttling and prevent liveness probe failures.",
    "rationale": "Renderer is throttled at 1 CPU (usage 0.93) with 41% throttling, causing timeouts. Increasing limit to 1.5 cores addresses the throttling without touching memory or other containers.",
